fn log_error(error: &SdkError, operation_id: &str, method: &str, url: &str, config: &ClientConfig) {
    if !config.logging.enabled {
        return;
    }
    let endpoint = match config.logging.endpoint.as_ref() {
        Some(value) => value.clone(),
        None => return,
    };
    let api_key = config.logging.api_key.clone();
    let name = match error {
        SdkError::Validation(_) => "SdkValidationError",
        SdkError::Http(_) => "SdkHttpError",
        SdkError::Api(_) => "SdkApiError",
        SdkError::ResponseDecode(_) => "SdkResponseDecodeError",
        SdkError::Network(_) => "SdkNetworkError",
        SdkError::Timeout(_) => "SdkTimeoutError",
    };

    // Rust errors carry no stack, so capture one here. With a debug build the
    // backtrace resolves to file:line in your code (release binaries are often
    // stripped); full structured frames + source need the `backtrace` crate.
    let stack = std::backtrace::Backtrace::force_capture().to_string();

    // eventId lets the monitoring backend deduplicate retried deliveries;
    // timestamp is epoch millis (the backend accepts that as well as ISO).
    let mut fields = vec![
        format!(r#""eventId":"{}""#, log_event_id()),
        format!(r#""timestamp":{}"#, log_now_millis()),
        r#""level":"error""#.to_string(),
        format!(r#""operationId":"{}""#, escape_json(operation_id)),
        format!(r#""method":"{}""#, escape_json(method)),
        format!(r#""path":"{}""#, escape_json(url)),
        format!(
            r#""error":{{"name":"{}","message":"{}","stack":"{}"}}"#,
            name,
            escape_json(&error.to_string()),
            escape_json(&stack)
        ),
    ];
    if let Some(code) = error.status_code() {
        fields.push(format!(r#""statusCode":{}"#, code));
    }
    if let Some(request_id) = error.request_id() {
        fields.push(format!(r#""requestId":"{}""#, escape_json(request_id)));
    }
    if let Some(environment) = config.logging.environment.as_ref() {
        fields.push(format!(r#""environment":"{}""#, escape_json(environment)));
    }
    if let Some(release) = config.logging.release.as_ref() {
        fields.push(format!(r#""release":"{}""#, escape_json(release)));
    }
    if let Some(user) = config.logging.user.as_ref() {
        let mut safe_user = user.clone();
        sanitize_json_value(&mut safe_user, config.logging.filter_pii);
        if let Ok(encoded) = serde_json::to_string(&safe_user) {
            fields.push(format!(r#""user":{}"#, encoded));
        }
    }
    if let Some(tags) = config.logging.tags.as_ref() {
        let mut safe_tags = tags.clone();
        sanitize_json_value(&mut safe_tags, config.logging.filter_pii);
        if let Ok(encoded) = serde_json::to_string(&safe_tags) {
            fields.push(format!(r#""tags":{}"#, encoded));
        }
    }
    let payload = format!("{{{}}}", fields.join(","));

    thread::spawn(move || {
        let mut req = ureq::post(&endpoint).set("Content-Type", "application/json");
        if let Some(key) = api_key {
            req = req.set("Authorization", &format!("Bearer {}", key));
        }
        let _ = req.send_string(&payload);
    });
}

