fn log_now_millis() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0)
}

/// Composes a middleware stack around `terminal`. The first middleware in the
/// slice is the outermost; `terminal` is the innermost call.
fn compose_middleware(stack: &[Arc<dyn Middleware>], terminal: BoxedNext) -> BoxedNext {
    if stack.is_empty() {
        return terminal;
    }
    let mut next: BoxedNext = terminal;
    for mw in stack.iter().rev() {
        let mw = Arc::clone(mw);
        let captured = next;
        next = Box::new(move |req| mw.handle(req, captured));
    }
    next
}

